import React, { useContext, useState } from "react";
import { AppContext } from "./AppContext";

const SettingsPanel = () => {
  const { theme, setTheme, language, setLanguage, user, setUser } = useContext(AppContext);

  const [age, setAge] = useState(user.age || "");
  const [gender, setGender] = useState(user.gender || "");
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");

  const handleThemeToggle = () => {
    setTheme(theme === "light" ? "dark" : "light");
  };

  const handleLanguageChange = (e) => {
    setLanguage(e.target.value);
  };

  const handleSaveUser = async () => {
    setSaving(true);
    setMessage("");
    try {
      // Example API call to your FastAPI backend
      const response = await fetch("/user/update", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ age, gender }),
      });

      if (!response.ok) throw new Error("Failed to update user info");

      setUser({ age, gender });
      setMessage("User info saved!");
    } catch (error) {
      setMessage("Error saving user info");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className={`settings-panel glassmorphism ${theme}`}>
      <h2>Settings</h2>

      {/* Language Selection */}
      <div className="setting-group">
        <label htmlFor="language-select">Language:</label>
        <select id="language-select" value={language} onChange={handleLanguageChange}>
          <option value="en">English</option>
          <option value="fr">French (Français)</option>
          <option value="ar">Arabic (العربية)</option>
        </select>
      </div>

      {/* Theme Toggle */}
      <div className="setting-group">
        <label>Theme:</label>
        <button onClick={handleThemeToggle} className="theme-toggle-btn">
          {theme === "light" ? "Switch to Dark Mode" : "Switch to Light Mode"}
        </button>
      </div>

      {/* User Info Edit */}
      <div className="setting-group">
        <label htmlFor="age-input">Age:</label>
        <input
          id="age-input"
          type="number"
          min="1"
          value={age}
          onChange={(e) => setAge(e.target.value)}
        />
      </div>

      <div className="setting-group">
        <label htmlFor="gender-select">Gender:</label>
        <select id="gender-select" value={gender} onChange={(e) => setGender(e.target.value)}>
          <option value="">Select Gender</option>
          <option value="male">Male</option>
          <option value="female">Female</option>
          <option value="other">Other</option>
        </select>
      </div>

      <button onClick={handleSaveUser} disabled={saving} className="save-btn">
        {saving ? "Saving..." : "Save User Info"}
      </button>

      {message && <p className="message">{message}</p>}

      <style jsx>{`
        .settings-panel {
          width: 320px;
          padding: 20px;
          border-radius: 15px;
          background: rgba(255 255 255 / 0.15);
          box-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.37);
          backdrop-filter: blur(10px);
          -webkit-backdrop-filter: blur(10px);
          border: 1px solid rgba(255 255 255 / 0.18);
          color: #fff;
          font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
          margin: 20px auto;
        }
        .settings-panel.dark {
          background: rgba(20 20 20 / 0.5);
          border-color: rgba(255 255 255 / 0.1);
          color: #eee;
        }
        h2 {
          margin-bottom: 15px;
          text-align: center;
        }
        .setting-group {
          margin-bottom: 15px;
          display: flex;
          flex-direction: column;
        }
        label {
          margin-bottom: 6px;
          font-weight: 600;
        }
        select,
        input[type="number"] {
          padding: 8px 10px;
          border-radius: 8px;
          border: none;
          outline: none;
          font-size: 1rem;
          background: rgba(255 255 255 / 0.25);
          color: #000;
          transition: background 0.3s ease;
        }
        select:focus,
        input[type="number"]:focus {
          background: rgba(255 255 255 / 0.4);
        }
        .theme-toggle-btn,
        .save-btn {
          padding: 10px 15px;
          border: none;
          border-radius: 10px;
          cursor: pointer;
          font-weight: 600;
          background: rgba(255 255 255 / 0.3);
          color: #000;
          transition: background 0.3s ease;
        }
        .theme-toggle-btn:hover,
        .save-btn:hover {
          background: rgba(255 255 255 / 0.5);
        }
        .settings-panel.dark select,
        .settings-panel.dark input,
        .settings-panel.dark .theme-toggle-btn,
        .settings-panel.dark .save-btn {
          background: rgba(0 0 0 / 0.5);
          color: #eee;
        }
        .settings-panel.dark .theme-toggle-btn:hover,
        .settings-panel.dark .save-btn:hover {
          background: rgba(255 255 255 / 0.15);
        }
        .message {
          margin-top: 12px;
          font-weight: 600;
          text-align: center;
          color: #90ee90;
        }
      `}</style>
    </div>
  );
};

export default SettingsPanel;
